import { highlightLines } from "@/lib/highlight";
import type { Trace } from "@/lib/trace";
import { MemoryStepperClient } from "./MemoryStepperClient";

type Props = {
  trace: Trace;
  start?: number;
  codeHeight?: number;
  interval?: number;
};

/**
 * <MemoryStepper trace={trace} />
 * code + stack + heap, one step at a time. the trace is either hand-written in the
 * mdx or generated by tools/tracer from a real run (import it from a .trace.json).
 */
export async function MemoryStepper({ trace, ...rest }: Props) {
  const lines = await highlightLines(trace.source);
  return <MemoryStepperClient trace={trace} lines={lines} {...rest} />;
}

/** same thing without the memory panes: walk the code line by line with notes + stdout. */
export async function CodeStepper({ trace, ...rest }: Props) {
  const lines = await highlightLines(trace.source);
  return <MemoryStepperClient trace={trace} lines={lines} memory={false} {...rest} />;
}
